//! Parity tests for the DataFrame part of `Pipe.filter_existing`
//! (`tests/fixtures/filter_existing.json`, generated by `tests/fixtures/gen_filter_existing.py`).

mod common;

use common::{cases, compare_frame, compare_values, decode, decode_frame, encode, load_fixture};
use indexmap::IndexMap;
use meerschaum_kernel::diff::{FilterExistingParams, filter_existing};
use meerschaum_kernel::enforce::{PipeDtypesContext, PipeInput, pipe_get_dtypes, pipe_is_tz_aware};
use meerschaum_kernel::value::Value;
use serde_json::Value as J;

fn str_map(j: &J) -> IndexMap<String, String> {
    j.as_object()
        .map(|o| {
            o.iter()
                .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                .collect()
        })
        .unwrap_or_default()
}

#[test]
fn filter_existing_parity() {
    let fixture = load_fixture("filter_existing");
    let mut failures = Vec::new();
    for case in cases(&fixture) {
        let name = case["name"].as_str().unwrap();
        let ok = &case["ok"];
        let columns = str_map(&case["columns"]);
        let configured = str_map(&case["configured_dtypes"]);
        let remote = str_map(&case["remote_dtypes"]);
        let p = &case["parameters"];
        let autoincrement = p["autoincrement"].as_bool().unwrap_or(false);
        let dtypes = pipe_get_dtypes(&configured, &remote, &columns, autoincrement);
        if serde_json::to_value(&dtypes).unwrap() != ok["pipe_dtypes"] {
            failures.push(format!(
                "{name}: get_dtypes {dtypes:?} != {}",
                ok["pipe_dtypes"]
            ));
        }
        let explicit = pipe_get_dtypes(&configured, &IndexMap::new(), &columns, autoincrement);
        let autotime = p["autotime"].as_bool().unwrap_or(false);
        let params = FilterExistingParams {
            columns: columns.clone(),
            configured_dtypes: configured.clone(),
            dtypes_ctx: PipeDtypesContext {
                tz_aware: pipe_is_tz_aware(&columns, &dtypes, autotime, "ts"),
                dtypes,
                explicit_dtypes: explicit,
                enforce: p["enforce"].as_bool().unwrap_or(true),
                mixed_numerics: p["mixed_numerics"].as_bool().unwrap_or(true),
            },
            autoincrement,
            autotime,
            static_: p["static"].as_bool().unwrap_or(false),
            include_unchanged_columns: case["kwargs"]["include_unchanged_columns"]
                .as_bool()
                .unwrap_or(false),
            date_bound_only: case["kwargs"]["date_bound_only"].as_bool().unwrap_or(false),
            enforce_dtypes: false,
            filter_params_index_limit: case["filter_params_index_limit"].as_u64().unwrap() as usize,
        };
        let input = match &case["df"] {
            J::Array(docs) => PipeInput::Docs(
                docs.iter()
                    .map(|d| {
                        d.as_object()
                            .unwrap()
                            .iter()
                            .map(|(k, v)| (k.clone(), decode(v)))
                            .collect::<IndexMap<String, Value>>()
                    })
                    .collect(),
            ),
            other => PipeInput::Frame(decode_frame(other)),
        };
        let backtrack = (!case["backtrack"].is_null()).then(|| decode_frame(&case["backtrack"]));
        let mut calls = Vec::new();
        let result = filter_existing(input, &params, |req| {
            calls.push(req.clone());
            backtrack.clone()
        });
        let (unseen, update, delta) = match result {
            Ok(r) => r,
            Err(e) => {
                failures.push(format!("{name}: unexpected error {e}"));
                continue;
            }
        };
        let expected_calls = ok["get_data_calls"].as_array().unwrap();
        if expected_calls.len() != calls.len() {
            failures.push(format!(
                "{name}: {} get_data calls, expected {}",
                calls.len(),
                expected_calls.len()
            ));
        }
        for (e, a) in expected_calls.iter().zip(calls.iter()) {
            for (key, val) in [("begin", &a.begin), ("end", &a.end)] {
                if let Err(m) = compare_values(&e[key], &encode(val)) {
                    failures.push(format!("{name}: {key}: {m}"));
                }
            }
            let eparams = e["params"].as_object().unwrap();
            let akeys: Vec<&String> = a.params.keys().collect();
            let ekeys: Vec<&String> = eparams.keys().collect();
            if akeys != ekeys {
                failures.push(format!("{name}: params keys {akeys:?} != {ekeys:?}"));
                continue;
            }
            for (k, vals) in &a.params {
                let evals = eparams[k].as_array().unwrap();
                if evals.len() != vals.len() {
                    failures.push(format!(
                        "{name}: params[{k}] length {} != {}",
                        vals.len(),
                        evals.len()
                    ));
                    continue;
                }
                for (ev, av) in evals.iter().zip(vals.iter()) {
                    if let Err(m) = compare_values(ev, &encode(av)) {
                        failures.push(format!("{name}: params[{k}]: {m}"));
                    }
                }
            }
        }
        // Guard against a vacuous comparator: `unseen` and `update` are never both the delta.
        if compare_frame(&ok["unseen"], &update, "self-check").is_ok()
            && compare_frame(&ok["update"], &unseen, "self-check").is_ok()
            && unseen.height() + update.height() > 0
            && unseen.height() != update.height()
        {
            failures.push(format!("{name}: comparator cannot tell unseen from update"));
        }
        for (label, frame) in [("unseen", &unseen), ("update", &update), ("delta", &delta)] {
            if let Err(m) = compare_frame(&ok[label], frame, &format!("{name}.{label}")) {
                failures.push(m);
            }
        }
    }
    if !failures.is_empty() {
        panic!(
            "{} filter_existing parity failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}
